const { errorGroups, rangeStart, rangeEnd } = $('Process Errors').first().json;

const errorList = errorGroups.map((g, i) => {
  const loc = g.container ? `${g.pod}/${g.container}` : g.pod;
  const resHint = g.resourceId ? ` resource=${g.resourceId.kind}/${g.resourceId.namespace}/${g.resourceId.name}` : '';
  const rbacHint = g.rbac ? ` rbac:SA=${g.saNs}/${g.saName} verb=${g.verb} resources=${(g.rbacResources||[]).join(',')}` : '';
  return `${i+1}. [${g.ns}] ${loc} (x${g.count} occurrences):${resHint}${rbacHint}
   ${g.sample.slice(0, 200)}`;
}).join('

');

const prompt = `You are a Kubernetes cluster health analyst. Analyze these error log groups from a homelab cluster (time window: ${rangeStart} to ${rangeEnd}).

For each group classify severity as:
- CRITICAL: service outage, data loss risk, or immediate action required
- WARNING: degraded service, recurring issue worth investigating
- NOISE: expected, transient, or known-harmless

Error groups:
${errorList}

Return exactly ${errorGroups.length} entries in "triaged", one per error group, in order. "index" is that group's number (1 to ${errorGroups.length}). Never merge groups, even when they share a cause.

Respond ONLY with valid JSON (no markdown fences):
{"triaged":[{"index":1,"severity":"WARNING","component":"infisical-operator","summary":"Recurring reconciler errors on secret CRs","severityRationale":"Reconciler keeps failing but cached token still valid, so cluster still works"}],"overall_severity":"WARNING","executive_summary":"One warning: infisical operator failing on secret rotation"}`;

return [{ json: { prompt, errorGroups, rangeStart, rangeEnd } }];
